    }
    case 'PUSH':
      receive(state, action.record, action.epoch);
      break;
    case 'SNAPSHOT': {
      const page = action.page;
      if (!page || page.kind !== 'snapshot' || page.tenant !== state.tenant) {
        throw new Error('Invalid snapshot');
      }
