       throw new Error(`action ${index} (${action?.type}): ${error.message}`);
     }
   }
   console.log(JSON.stringify({state, view: selectView(state)}));
 } catch (error) {
   process.stderr.write(`trace: ${error.message}\n`);
   process.exitCode = 1;
 }

